#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "scheduler.h"
static void fail(char *e,size_t n,const char *s){if(e&&n)snprintf(e,n,"%s",s);} static int add(Tournament *t,Match m){if(t->match_count==t->match_capacity){size_t c=t->match_capacity?t->match_capacity*2:16;Match *p=realloc(t->matches,c*sizeof *p);if(!p)return 0;t->matches=p;t->match_capacity=c;}t->matches[t->match_count++]=m;return 1;}
int schedule_generate(Tournament *t,char *e,size_t n){size_t count=t->team_count, slots, round, i;int *ring;if(count<2){fail(e,n,"Add at least two teams before generating a schedule");return 0;}free(t->matches);t->matches=NULL;t->match_count=t->match_capacity=0;t->next_match_id=1;slots=count%2?count+1:count;ring=malloc(slots*sizeof *ring);if(!ring){fail(e,n,"Out of memory");return 0;}for(i=0;i<count;i++)ring[i]=t->teams[i].id;if(slots>count)ring[count]=0;t->rounds=(int)(slots-1);
 for(round=1;round<slots;round++){for(i=0;i<slots/2;i++){Match m={0};m.id=t->next_match_id++;m.round=(int)round;m.home_id=ring[i];m.away_id=ring[slots-1-i];m.home_score=m.away_score=-1;m.status=(m.home_id==0||m.away_id==0)?MATCH_BYE:MATCH_UPCOMING;if(!add(t,m)){free(ring);fail(e,n,"Out of memory");return 0;}}int last=ring[slots-1];for(i=slots-1;i>1;i--)ring[i]=ring[i-1];ring[1]=last;}free(ring);t->status=TOURNAMENT_ACTIVE;return 1;}
int schedule_validate(const Tournament *t,char *e,size_t n){size_t i,j;int expected=(int)(t->team_count*(t->team_count-1)/2),actual=0;if(t->rounds!=(int)(t->team_count%2?t->team_count:t->team_count-1)){fail(e,n,"Wrong round count");return 0;}for(i=0;i<t->match_count;i++){const Match *a=&t->matches[i];if(a->status==MATCH_BYE)continue;actual++;for(j=i+1;j<t->match_count;j++){const Match *b=&t->matches[j];if(b->status==MATCH_BYE)continue;if((a->home_id==b->home_id&&a->away_id==b->away_id)||(a->home_id==b->away_id&&a->away_id==b->home_id)){fail(e,n,"Duplicate pairing");return 0;}if(a->round==b->round&&(a->home_id==b->home_id||a->home_id==b->away_id||a->away_id==b->home_id||a->away_id==b->away_id)){fail(e,n,"Same-round conflict");return 0;}}}if(actual!=expected){fail(e,n,"Wrong match count");return 0;}return 1;}
